mapper.select:
SELECT mt.id, mt.title, mt.content, mt.category, mt.publish_date, mt.is_published, mt.create_time, mt.update_time, mt.create_user, mt.update_user, ca.name AS createUserName, ua.name AS updateUserName FROM moving_tips mt LEFT JOIN admin ca ON mt.create_user = ca.id LEFT JOIN admin ua ON mt.update_user = ua.id
AND mt.title LIKE CONCAT('%', #{title}, '%')
AND mt.content LIKE CONCAT('%', #{content}, '%')
AND mt.category LIKE CONCAT('%', #{category}, '%')
AND mt.is_published = #{isPublished}
AND mt.publish_date >= #{publishDateStart}
AND mt.publish_date <= #{publishDateEnd}
ORDER BY mt.publish_date DESC
